<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';
function saas_plan_row(string $slug):array{$s=saas_db()->prepare('SELECT * FROM saas_plans WHERE slug=? AND active=1 LIMIT 1');$s->execute([$slug]);return $s->fetch(PDO::FETCH_ASSOC)?:[];}
function saas_sync_user_credits(int $uid):array{$db=saas_db();$db->exec("ALTER TABLE creator_users ADD COLUMN IF NOT EXISTS credit_period_started_at DATETIME NULL");$db->exec("ALTER TABLE creator_users ADD COLUMN IF NOT EXISTS credit_period_ends_at DATETIME NULL");$s=$db->prepare('SELECT id,plan,credits,credit_period_started_at,credit_period_ends_at FROM creator_users WHERE id=? LIMIT 1');$s->execute([$uid]);$u=$s->fetch(PDO::FETCH_ASSOC);if(!$u)throw new RuntimeException('User not found');$plan=saas_plan_row((string)$u['plan'])?:saas_plan_row('free');$end=$u['credit_period_ends_at']?strtotime((string)$u['credit_period_ends_at']):false;if(!$u['credit_period_started_at']||!$end||$end<=time()){$credits=(int)$plan['monthly_credits'];$db->prepare("UPDATE creator_users SET credits=?,credit_period_started_at=NOW(),credit_period_ends_at=DATE_ADD(NOW(),INTERVAL 1 MONTH) WHERE id=?")->execute([$credits,$uid]);$u['credits']=$credits;$u['credit_period_ends_at']=date('Y-m-d H:i:s',strtotime('+1 month'));}return $u;}
function saas_use_credit(int $uid,string $toolSlug):array{$db=saas_db();saas_sync_user_credits($uid);$db->beginTransaction();try{$s=$db->prepare('SELECT credits FROM creator_users WHERE id=? FOR UPDATE');$s->execute([$uid]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row||(int)$row['credits']<1){$db->rollBack();return['ok'=>false,'credits'=>0,'message'=>'You have used all your credits. Upgrade your plan to continue.'];}$db->prepare('UPDATE creator_users SET credits=credits-1 WHERE id=? AND credits>0')->execute([$uid]);$new=max(0,(int)$row['credits']-1);$db->prepare('INSERT INTO creator_credit_transactions(user_id,type,amount,balance_after,description) VALUES(?,?,?,?,?)')->execute([$uid,'tool_generation',-1,$new,'1 credit used for '.$toolSlug]);$db->prepare('INSERT INTO tool_usage(user_id,tool_slug,ip_hash) VALUES(?,?,?)')->execute([$uid,$toolSlug,hash('sha256',(string)($_SERVER['REMOTE_ADDR']??''))]);$db->commit();return['ok'=>true,'credits'=>$new,'message'=>'1 credit used.'];}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
if(basename((string)($_SERVER['SCRIPT_FILENAME']??''))===basename(__FILE__)){$uid=saas_user_id();if($_SERVER['REQUEST_METHOD']!=='POST'||!$uid){http_response_code($uid?405:401);header('Content-Type: application/json');echo json_encode(['ok'=>false,'message'=>$uid?'Method not allowed':'Login required']);exit;}$tool=preg_replace('/[^a-z0-9-]/','',strtolower((string)($_POST['tool']??'tool')))?:'tool';try{$r=saas_use_credit($uid,$tool);header('Content-Type: application/json');echo json_encode($r);}catch(Throwable $e){http_response_code(500);header('Content-Type: application/json');echo json_encode(['ok'=>false,'message'=>'Credit service unavailable']);error_log($e->getMessage());}}